// ─── Types ──────────────────────────────────────────────────────────────
export interface Problem {
    id: string;
    title: string;
    difficulty: "Easy" | "Medium" | "Hard";
    topic: string;
    url: string;
    acceptance?: string;
    frequency?: "High" | "Medium" | "Low";
}

export interface Company {
    id: string;
    name: string;
    logo: string;
    gradient: string;
    tier: "FAANG" | "Product" | "Service" | "Finance" | "Startup";
    problems: Problem[];
    description: string;
    avgPackage: string;
    interviewRounds: string[];
    interviewTips?: string[];
    resources?: { label: string; url: string }[];
}

// ─── Problem Template (no ID — generated per company) ───────────────────
export type PT = Omit<Problem, "id">;

// ─── Helper: assign unique IDs to problems ──────────────────────────────
export const mkP = (prefix: string, pool: PT[], variant = 0, count = 8): Problem[] => {
    // Generate a deterministic offset based on the company ID (prefix)
    const offset = prefix.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    // Combine offset with variant to get a unique start index
    const start = (offset + variant * 43) % pool.length;
    const selected: PT[] = [];
    for (let i = 0; i < count; i++) selected.push(pool[(start + i) % pool.length]);
    return selected.map((p, i) => ({ ...p, id: `${prefix}${i + 1}` }));
};

// ─── Factory Functions ──────────────────────────────────────────────────
export const mkSvc = (id: string, name: string, logo: string, grad: string, desc: string, pkg: string, v = 0, rounds?: string[], tips?: string[], res?: { label: string; url: string }[]): Company => ({
    id, name, logo, gradient: grad, tier: "Service", description: desc, avgPackage: pkg,
    interviewRounds: rounds || ["Aptitude Test", "Technical Round", "HR Round"],
    problems: mkP(id, SVC_POOL, v, 30),
    interviewTips: tips,
    resources: res,
});

export const mkProd = (id: string, name: string, logo: string, grad: string, desc: string, pkg: string, v = 0, rounds?: string[], tips?: string[], res?: { label: string; url: string }[]): Company => ({
    id, name, logo, gradient: grad, tier: "Product", description: desc, avgPackage: pkg,
    interviewRounds: rounds || ["Online Assessment", "Technical Round x2", "HR Round"],
    problems: mkP(id, PROD_POOL, v, 60),
    interviewTips: tips,
    resources: res,
});

export const mkFin = (id: string, name: string, logo: string, grad: string, desc: string, pkg: string, v = 0, rounds?: string[], tips?: string[], res?: { label: string; url: string }[]): Company => ({
    id, name, logo, gradient: grad, tier: "Finance", description: desc, avgPackage: pkg,
    interviewRounds: rounds || ["Online Assessment", "Technical Round", "HR Round"],
    problems: mkP(id, FIN_POOL, v, 30),
    interviewTips: tips,
    resources: res,
});

export const mkStart = (id: string, name: string, logo: string, grad: string, desc: string, pkg: string, v = 0, rounds?: string[], tips?: string[], res?: { label: string; url: string }[]): Company => ({
    id, name, logo, gradient: grad, tier: "Startup", description: desc, avgPackage: pkg,
    interviewRounds: rounds || ["Technical Round", "HR Round"],
    problems: mkP(id, STRT_POOL, v, 30),
    interviewTips: tips,
    resources: res,
});

